xml.Script:
        clYellow       := 'FFFF00';
        clLightBlue    := '2828FF';
        clBlue         := '0000A0';
        clBrown        := '800000';
        clOrange       := 'FF6000';
        clLightViolett := 'FF0080';
        clRed          := 'FF0000';
        clLightGreen   := '00FF00';
        clGreen        := '008000';
        clViolett      := '800080';
        clCyan         := '00DCB4';
        clWhite        := 'FFFFFF';

        mAngle := ArcTan(0.5);
        As := sin(mAngle);
        Ac := cos(mAngle);
        sAngle := PI * 2 / 5;

        // axes
        ax[0] := 0;
        ay[0] := 0;
        az[0] := 1;
        for i := 1 to 5 do begin
            ax[i] := sin(sAngle * (i - 1)) * Ac;
            ay[i] := cos(sAngle * (i - 1)) * Ac;
            az[i] := As;
        end;

        R := 1.1;
        Rsin := R * sin(mAngle);
        Rcos := R * cos(mAngle);

        X[0] := 0;
        Y[0] := 0;
        Z[0] := R;
        for i := 1 to 5 do begin
            X[i] := Rcos * sin(sAngle * (i - 1));
            Y[i] := Rcos * cos(sAngle * (i - 1));
            Z[i] := Rsin;
        end;
        for i := 6 to 10 do begin
            X[i] := Rcos * sin(sAngle * (i - 0.5));
            Y[i] := Rcos * cos(sAngle * (i - 0.5));
            Z[i] := -Rsin;
        end;
        X[11] := 0;
        Y[11] := 0;
        Z[11] := -R;

        dAngle := (Arctan(2) + Arcsin(2/3)) / 2;
        dAngle2 := (Arctan(2) - Arcsin(2/3)) / 2;
        R1 := RSin / sin(dAngle);
        Rsin := R1 * sin(dAngle);
        Rcos := R1 * cos(dAngle);
        R2sin := R1 * sin(dAngle2);
        R2cos := R1 * cos(dAngle2);

        for i := 0 to 4 do begin
            x1[i] := Rcos * sin(sAngle * (i - 0.5));
            y1[i] := Rcos * cos(sAngle * (i - 0.5));
            z1[i] := Rsin;
        end;

        for i := 5 to 9 do begin
            x1[i] := R2cos * sin(sAngle * (i - 0.5));
            y1[i] := R2cos * cos(sAngle * (i - 0.5));
            z1[i] := R2sin;
        end;

        for i := 10 to 14 do begin
            x1[i] := R2cos * sin(sAngle * i);
            y1[i] := R2cos * cos(sAngle * i);
            z1[i] := -R2sin;
        end;

        for i := 15 to 19 do begin
            x1[i] := Rcos * sin(sAngle * i);
            y1[i] := Rcos * cos(sAngle * i);
            z1[i] := -Rsin;
        end;

        d2 := R * sin(mAngle) - 0.01;
        d1 := d2 - R * 0.125;
        DCut := d2 + R * 0.125;
